# Fit the storm set's feather circlet, generated by Meshy from the owner's three-view sheet
# (assets/meshy/outfits/feather_circlet_reference.png → feather_circlet_meshy.glb: an arc of
# feathers on a twisted cord, open at the back), round the hero's own hair
# (public/models/hero_chibi_hair.glb), the frame the game draws it in over that hair
# (data/models.json `withHair`). The arc is unbent along its middle line and bent again round the
# hair at the cord's height, its inside just off the hair, its ends round the temples.
#   PYTHONPATH=<bpy dir> python3 scripts/fit-feather-circlet.py
import bpy, bmesh, numpy as np

SRC, HAIR, OUT = ('assets/meshy/outfits/feather_circlet_meshy.glb', 'public/models/hero_chibi_hair.glb',
                  'public/models/outfits/feather_circlet.glb')
Z_FRONT, Z_SIDE = 1.045, 1.06  # the cord's height over the forehead and over the ears
SPAN = 1.25                    # how far round the head each end of the arc reaches (radians from the front)
SIZE = 0.65                    # its feathers' height and depth for that length (1: the sheet's)
GAP = 0.006                    # the arc's inside off the hair
TRIS, TEX = 2000, 1024

bpy.ops.wm.read_factory_settings(use_empty=True)
bpy.ops.import_scene.gltf(filepath=HAIR)
hob = [o for o in bpy.data.objects if o.type == 'MESH'][0]
H = np.array([tuple(hob.matrix_world @ v.co) for v in hob.data.vertices])
ring = H[(H[:, 2] > Z_FRONT - 0.04) & (H[:, 2] < Z_SIDE + 0.04)]
AX, AY = (ring[:, 0].min() + ring[:, 0].max()) / 2, (ring[:, 1].min() + ring[:, 1].max()) / 2
# the hair's outside round the cord: its radius at each angle (past most of its points: a spike
# may poke through), smoothed round the head; 0 is the front (-Y), + toward +X
NA = 72
ang = np.arctan2(H[:, 0] - AX, -(H[:, 1] - AY)); rad = np.hypot(H[:, 0] - AX, H[:, 1] - AY)
R = np.zeros(NA)
for j in range(NA):
    a = -np.pi + (j + 0.5) * 2 * np.pi / NA
    z = Z_FRONT + (Z_SIDE - Z_FRONT) * min(abs(a) / (np.pi / 2), 1)
    m = (np.abs(H[:, 2] - z) < 0.02) & (np.abs((ang - a + np.pi) % (2 * np.pi) - np.pi) < 0.15)
    R[j] = np.percentile(rad[m], 85) if m.any() else 0
R[R == 0] = R[R > 0].min()
for _ in range(3):
    R = sum(w * np.roll(R, d) for w, d in zip((1 / 16, 4 / 16, 6 / 16, 4 / 16, 1 / 16), range(-2, 3)))


def hair_r(a):
    return np.interp(a, -np.pi + (np.arange(NA) + 0.5) * 2 * np.pi / NA, R, period=2 * np.pi)


for o in [o for o in bpy.data.objects]: bpy.data.objects.remove(o)
bpy.ops.import_scene.gltf(filepath=SRC)
g = [o for o in bpy.data.objects if o.type == 'MESH'][0]
g.data.transform(g.matrix_world); g.matrix_world.identity()
# fewer triangles (Meshy's remesh gives ~6000; a helm is drawn on one hero)
dec = g.modifiers.new('dec', 'DECIMATE'); dec.ratio = TRIS / len(g.data.polygons)
bpy.context.view_layer.objects.active = g; bpy.ops.object.modifier_apply(modifier='dec')
V = np.array([tuple(v.co) for v in g.data.vertices])
# the arc seen from above: a circle round a centre behind it (+Y, the face is at -Y), fitted to its
# points; each point's angle on it gives its place along the arc, and its distance past the arc's
# inside at that angle how far out it stands
best = None
for yc in np.linspace(0.3, 4, 371):
    rho = np.hypot(V[:, 0], V[:, 1] - yc); e = rho.std()
    if best is None or e < best[0]: best = (e, yc)
yc = best[1]
phi = np.arctan2(V[:, 0], yc - V[:, 1]); rho = np.hypot(V[:, 0], V[:, 1] - yc)
bins = np.linspace(phi.min(), phi.max(), 31)
inside = np.array([rho[np.abs(phi - p) < (bins[1] - bins[0])].min() for p in bins])
# the cord's height: the middle of the arc's front
zc = np.median(V[np.abs(phi) < 0.05, 2])
# one scale for the whole arc: its ends reach SPAN round the hair at the front's radius
k = SPAN * hair_r(0) / (max(-phi.min(), phi.max()) * np.median(inside))
for v, p, q in zip(g.data.vertices, phi, rho):
    out = q - np.interp(p, bins, inside)
    a = p * SPAN / max(-phi.min(), phi.max())
    r = hair_r(a) + GAP + out * k * SIZE
    h = Z_FRONT + (Z_SIDE - Z_FRONT) * min(abs(a) / (np.pi / 2), 1) + (v.co.z - zc) * k * SIZE
    v.co = (AX + r * np.sin(a), AY - r * np.cos(a), h)
g.data.update()
img = [n for n in g.material_slots[0].material.node_tree.nodes if n.type == 'TEX_IMAGE'][0].image
img.scale(TEX, TEX)
bpy.ops.object.select_all(action='DESELECT'); g.select_set(True)
print('feather_circlet tris', len(g.data.polygons), 'scale %.3f' % k)
bpy.ops.export_scene.gltf(filepath=OUT, use_selection=True, export_format='GLB',
                          export_image_format='JPEG', export_jpeg_quality=88, export_yup=True)
